import { readFile } from "node:fs/promises";
import path from "node:path";
import puppeteer from "puppeteer";
import sanitizeHtml from "sanitize-html";
import { prisma } from "@/lib/prisma";
import { escapeHtml as h, type ReportSettings } from "./config";
import type { Metrics } from "./metrics";

const company = "Khyati Precious Gems Private Limited";
export function sanitizeLogoSvg(svg: string) {
 if (!/<svg[\s>]/i.test(svg) || /<!DOCTYPE|<!ENTITY|<script|<foreignObject|(?:href|xlink:href)\s*=|url\(\s*(?!#)/i.test(svg)) throw new Error("Company logo SVG contains unsupported or external content");
 const cleaned = sanitizeHtml(svg, { allowedTags: ["svg", "g", "path", "rect", "circle", "ellipse", "polygon", "polyline", "line", "defs", "linearGradient", "stop"], allowedAttributes: { "*": ["xmlns", "viewBox", "width", "height", "d", "fill", "stroke", "stroke-width", "transform", "x", "y", "cx", "cy", "r", "rx", "ry", "points", "id", "offset", "stop-color", "opacity", "x1", "x2", "y1", "y2"] }, parser: { lowerCaseTags: false, lowerCaseAttributeNames: false } });
 if (!cleaned.includes("<svg") || !/<(?:path|rect|circle|ellipse|polygon|polyline|line)[\s>]/.test(cleaned)) throw new Error("Company logo SVG has no supported artwork");
 return cleaned;
}
export const money = (values: Record<string, number>) => Object.entries(values).map(([c, n]) => new Intl.NumberFormat("en-IN", { style: "currency", currency: c }).format(n)).join(" · ") || "Unavailable";
const percent = (value: number | null | undefined) => value == null ? "N/A" : `${value > 0 ? "+" : ""}${value.toFixed(1)}%`;
const changeSummary = (shop: Metrics["shops"][number]) => shop.orderDataAvailable ? `Orders ${percent(shop.orderChange)} · Units ${percent(shop.unitChange)} · ${Object.entries(shop.revenueChange).map(([currency, change]) => `${currency} ${percent(change)}`).join(" · ") || "Value N/A"}` : "N/A · order sync incomplete";
const timestamp = (value: string | null, timezone: string) => value ? new Intl.DateTimeFormat("en-IN", { timeZone: timezone, dateStyle: "medium", timeStyle: "short" }).format(new Date(value)) : "No sync recorded";
const orderSyncLabel = (state: string) => ({ CURRENT: "Complete after period end", STALE: "Before period end", NO_SYNC: "No completed order sync", IN_PROGRESS: "In progress", PARTIAL: "Partial / failed records", FAILED: "Failed", DISCONNECTED: "Disconnected" }[state] || "Unavailable");
const noteCard = (title: string, message: string) => `<div class="chart"><h3>${h(title)}</h3><p class="muted">${h(message)}</p></div>`;
export function bars(title: string, rows: Array<[string, number]>, color = "#168879") {
 const max = Math.max(1, ...rows.map(r => r[1]));
 return `<div class="chart"><h3>${h(title)}</h3><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 620 ${Math.max(55, rows.length * 29 + 12)}" role="img" aria-label="${h(title)}">${rows.map(([label, n], i) => `<text x="0" y="${i * 29 + 20}" font-size="12" fill="#334155">${h(label.slice(0, 27))}</text><rect x="200" y="${i * 29 + 5}" width="${Math.max(0, n) / max * 330}" height="19" rx="3" fill="${color}"/><text x="${210 + Math.max(0, n) / max * 330}" y="${i * 29 + 20}" font-size="12" fill="#334155">${h(Number(n.toFixed(2)))}</text>`).join("")}${!rows.length ? '<text x="0" y="30" font-size="13">No covered data in this period</text>' : ""}</svg></div>`;
}
const table = (headers: string[], rows: unknown[][]) => `<table><thead><tr>${headers.map(x => `<th>${h(x)}</th>`).join("")}</tr></thead><tbody>${rows.length ? rows.map(row => `<tr>${row.map(x => `<td>${h(x)}</td>`).join("")}</tr>`).join("") : `<tr><td colspan="${headers.length}">No covered records in this period.</td></tr>`}</tbody></table>`;
export function reportHtml(m: Metrics, s: ReportSettings, logo: string, font: string, mode: string) {
 const block = (key: keyof ReportSettings["sections"], title: string, body: string, startNewPage = false) => s.sections[key] ? `<section${startNewPage ? ' style="break-before:page"' : ""}><h2>${h(title)}</h2>${body}</section>` : "";
 const ordersAvailable = m.orderCoverage.complete;
 const unavailableOrderMessage = `Unavailable: a complete successful order sync after ${m.period.endDay} (${m.period.timezone}) is missing for ${m.orderCoverage.unavailableShops.map(x => x.name).join(", ") || "the selected shop scope"}. Stored records are not evidence of zero demand.`;
 const currentOrders = ordersAvailable ? m.current.count : "Unavailable";
 const currentUnits = ordersAvailable ? m.current.units : "Unavailable";
 const currentRecordedValue = ordersAvailable ? money(m.current.totals) : "Unavailable — order sync incomplete";
 const currencies = [...new Set([...Object.keys(m.current.totals), ...Object.keys(m.previous?.totals || {})])];
 const exceptionRows = m.exceptions.flatMap(x => {
  const missing = x.missing.filter(field => field !== "Image" && field !== "Certificate number");
  return missing.length ? [[x.sku + " / " + x.name, x.status + " / " + x.listings, missing.join(", "), `WARNING / Add or verify ${missing.join(", ")}.`]] : [];
 });
 const orderCharts = ordersAvailable ? `${bars("Orders by marketplace / shop", m.shops.map(x => [`${x.platform} / ${x.name}`, x.orders]))}${currencies.map(c => bars(`Recorded order value by shop (${c})`, m.shops.map(x => [x.name, x.value[c] || 0])) + bars(`Daily recorded order value (${c})`, Object.entries(m.current.daily).map(([d, v]) => [d, v[c] || 0]))).join("")}${s.comparisons && m.previous ? bars("Order comparison", [["Previous week", m.previous.count], ["Current week", m.current.count]]) : ""}` : noteCard("Marketplace order charts unavailable", unavailableOrderMessage);
 const charts = s.charts ? `${orderCharts}${bars("Complete versus incomplete physical SKUs", [["Complete", m.inventory.physicalSkus - m.inventory.incomplete], ["Incomplete", m.inventory.incomplete]])}${bars("Missing-field breakdown", Object.entries(m.inventory.missingFields), "#b89555")}` : "";
 const comparisonText = m.comparisons ? `Week-over-week: orders ${ordersAvailable ? percent(m.comparisons.orders) : "N/A — order sync incomplete"}, units ${ordersAvailable ? percent(m.comparisons.units) : "N/A — order sync incomplete"}, confirmed new listings ${percent(m.comparisons.newListings)}. Revenue change is unavailable unless order sync coverage is complete.` : "";
 const syncRows = m.shops.map(x => [x.name, timestamp(x.lastListingSyncAt, m.period.timezone), timestamp(x.lastOrderSyncAt, m.period.timezone), orderSyncLabel(x.orderSyncState), x.failedSyncs, x.failedListingRecords]);
 const reportGeneratedAt = `${timestamp(m.generatedAt, m.period.timezone)} (${m.period.timezone})`;
 const gemstones = Object.entries(m.inventory.byGemstone).sort((a, b) => b[1] - a[1] || a[0].localeCompare(b[0]));
 const gemstoneHalf = Math.ceil(gemstones.length / 2);
 const gemstoneRows = Array.from({ length: gemstoneHalf }, (_, index) => [gemstones[index][0], gemstones[index][1], gemstones[index + gemstoneHalf]?.[0] || "", gemstones[index + gemstoneHalf]?.[1] ?? ""]);
 return `<!doctype html><html><head><meta charset="utf-8"><style>@font-face{font-family:Report;src:url(data:font/ttf;base64,${font})}*{box-sizing:border-box}body{font-family:Report,Arial,sans-serif;font-size:10px;line-height:1.5;color:#25364a;background:#fff;color-scheme:light;margin:0}header{border-bottom:3px solid #b89555;padding:0 0 20px;margin-bottom:22px}header img{width:155px;height:65px;object-fit:contain;object-position:left}.eyebrow{color:#168879;letter-spacing:2px;text-transform:uppercase;font-size:10px}h1{font-size:27px;line-height:1.2;color:#102b45;margin:12px 0}h2{font-size:18px;color:#102b45;border-bottom:1px solid #d7e1e7;padding:10px 0 7px;margin:18px 0 12px}h3{font-size:12px}section{margin:18px 0}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.card{background:#f0f5f6;border-top:3px solid #168879;padding:12px;break-inside:avoid}.number{font-size:24px;color:#102b45}.notice{padding:11px;background:#fff6e6;border-left:3px solid #b89555;margin:10px 0}.critical{border-color:#bd3636}table{width:100%;border-collapse:collapse;margin:10px 0;font-size:9px;table-layout:fixed}thead{display:table-header-group}tr{break-inside:avoid}th{background:#102b45;color:white;text-align:left}td,th{padding:7px;border-bottom:1px solid #dfe7ea;overflow-wrap:anywhere;vertical-align:top}tbody tr:nth-child(even){background:#f5f8fa}.chart{break-inside:avoid;border:1px solid #dfe7ea;padding:12px;margin:12px 0}svg{width:100%;height:auto}.muted{color:#64748b}li{margin:7px 0}.tag{font-weight:bold;color:#a06e1d}</style></head><body><header><img src="${logo}" alt="Khyati Gems"><div class="eyebrow">Business intelligence / ${h(mode)}</div><h1>${h(s.name)}</h1><strong>${company}</strong><p>${h(m.period.startDay)} – ${h(m.period.endDay)} · ${h(m.period.timezone)}<br>Generated ${h(reportGeneratedAt)} · Data coverage: ${h(m.dataQuality)}</p></header>
 ${block("executive", "Executive summary", `<div class="cards">${[["In-stock physical SKUs", m.inventory.inStock], ["Distinct marketplace order records", currentOrders], ["Eligible item units", currentUnits], ["Confirmed new listings (partial)", m.newListings.length], ["Incomplete physical SKUs", m.inventory.incomplete], ["Critical / warning alerts", `${m.alerts.filter(x => x.severity === "CRITICAL").length} / ${m.alerts.filter(x => x.severity === "WARNING").length}`]].map(([a, b]) => `<div class="card">${h(a)}<div class="number">${h(b)}</div></div>`).join("")}</div><p>Recorded marketplace order value: <strong>${h(currentRecordedValue)}</strong>. Net sales, settlements and consolidated INR: unavailable.</p>${comparisonText ? `<p>${h(comparisonText)}</p>` : ""}${m.alerts.slice(0, 5).map(x => `<div class="notice ${x.severity === "CRITICAL" ? "critical" : ""}"><strong>${h(x.severity)}: ${h(x.message)}</strong><br>${h(x.action)}</div>`).join("")}`)}
 ${block("inventory", "Inventory overview — generation-time snapshot", `<p>${m.inventory.physicalSkus} unique physical SKUs. ${m.soldPhysicalSkus} distinct physical SKUs have ERP sale records during the period. This separate ledger is not added to marketplace quantities.</p>${table(["Status", "Physical SKUs"], Object.entries(m.inventory.byStatus))}${table(["Gemstone", "Physical SKUs", "Gemstone", "Physical SKUs"], gemstoneRows)}${s.valuation ? `<p>In-stock cost valuation: ${h(m.inventory.costValuation)}; asking-price valuation: ${h(m.inventory.askingValuation)}. ${h(m.inventory.valuationCurrency)}. One value per physical SKU; neither is realized revenue.</p>` : ""}`)}
 ${block("marketplaces", "Marketplace and shop performance", `${s.comparisons ? `<p class="muted">Order changes compare this reporting week with the previous week and require complete order sync coverage. Percentage is N/A when the previous week was zero. Inventory/listing counts are current snapshots.</p>` : ""}${!ordersAvailable ? `<p class="notice">${h(unavailableOrderMessage)}</p>` : ""}${table(["Shop / platform", "Connection", "Active listings now", "New publications", "Orders / units", "Recorded order value", ...(s.comparisons ? ["Change vs previous week"] : [])], m.shops.map(x => [x.name + " / " + x.platform, x.connected ? "Connected" : "Disconnected", x.activeListings, x.newListings ?? "Unavailable", x.orderDataAvailable ? `${x.orders} / ${x.units}` : "Unavailable", x.orderDataAvailable ? money(x.value) : "Unavailable", ...(s.comparisons ? [changeSummary(x)] : [])]))}`)}
 ${s.syncHealth ? block("sync", "Synchronization health", `<p class="muted">Timestamps use ${h(m.period.timezone)}. Listing sync status supports the active-listing snapshot. Order metrics require a complete successful order sync after the reporting period ended.</p>${table(["Shop", "Last listing sync", "Last order sync", "Order data for period", "Failed sync logs", "Listing errors now"], syncRows)}`) : ""}
 ${block("availability", "Stock availability and sold inventory", `<p>Current in-stock physical SKUs: ${m.inventory.inStock}. Distinct physical SKUs with ERP sales in the reporting period: ${m.soldPhysicalSkus}. Reserved and inactive categories use the recorded stock statuses; historical availability is unavailable.</p>`)}
 ${block("orders", "Orders received", ordersAvailable ? `<p>${m.current.count} distinct platform/external order IDs; ${m.current.units} eligible item units. ${m.current.cancelled} recognized cancelled-status orders and ${m.current.refunded} recognized refunded-status orders excluded from value and units. ${m.current.unknownAmounts} eligible orders lack valid amounts.</p>` : `<p>${h(unavailableOrderMessage)} Counts, units and value are suppressed until order synchronization is complete for every shop in scope.</p>`)}
 ${block("revenue", "Revenue and financial coverage", `<p>Recorded marketplace order value by original currency: ${h(currentRecordedValue)}.</p><p>Average eligible recorded order value (per currency): ${h(ordersAvailable ? money(m.current.averageOrderValue) : "Unavailable — order sync incomplete")}. Gross sales, net sales, tax, shipping, discount and refund amounts cannot be reliably separated. Cash receipts, settlements and historical currency conversion are unavailable.</p>${table(["Currency", "Current order value", "Previous", "Change"], currencies.length ? currencies.map(c => [c, ordersAvailable ? m.current.totals[c] ?? "No recorded value" : "Unavailable", ordersAvailable ? m.previous?.totals[c] ?? "No recorded value" : "Unavailable", !ordersAvailable ? "N/A — incomplete sync" : m.comparisons?.revenue[c] == null ? "N/A" : `${m.comparisons.revenue[c]!.toFixed(1)}%`]) : [["—", ordersAvailable ? "No recorded value" : "Unavailable", ordersAvailable ? "No recorded value" : "Unavailable", "N/A"]])}`)}
 ${block("comparisons", "Historical comparisons", s.comparisons && m.previous ? table(["Metric", "This week", "Last week", "Change"], [["Orders", ordersAvailable ? m.current.count : "Unavailable", ordersAvailable ? m.previous.count : "Unavailable", ordersAvailable ? percent(m.comparisons?.orders) : "N/A — incomplete sync"], ["Units", ordersAvailable ? m.current.units : "Unavailable", ordersAvailable ? m.previous.units : "Unavailable", ordersAvailable ? percent(m.comparisons?.units) : "N/A — incomplete sync"], ["Confirmed new listings", m.newListings.length, m.previousPublished, percent(m.comparisons?.newListings)]]) : "Comparisons disabled or unavailable.")}
 ${block("refunds", "Returns and cancellations", `<p>${ordersAvailable ? `Recognized cancelled-status marketplace orders: ${m.current.cancelled}; recognized refunded-status orders: ${m.current.refunded}.` : "Marketplace cancellation/refund counts are unavailable because order sync coverage is incomplete."} Comprehensive marketplace cancellation/refund counts are unavailable. ERP returns (separate ledger): ${m.erpReturns.records ?? "Unavailable"} records / ${m.erpReturns.units ?? "Unavailable"} units. Financial refund value is unavailable.</p>`)}
 ${block("listings", "Confirmed new marketplace listings", `<p>Coverage is partial: only verified successful ERP eBay publication markers. Failed attempts and imported listing creation dates are excluded.</p>${table(["Shop / platform", "SKU", "Title", "Listing ID", "Published (UTC)"], m.newListings.map(x => [m.shops.find(y => y.id === x.shopId)?.name || x.platform, x.sku, x.name, x.externalId, x.publishedAt]))}`)}
 ${block("completeness", "Inventory completeness", `<p>${m.inventory.incomplete} of ${m.inventory.physicalSkus} physical SKUs incomplete (${m.inventory.incompletePercent.toFixed(1)}%). Certificate requirements apply only to configured categories.</p>${table(["Missing field", "Affected SKUs"], Object.entries(m.inventory.missingFields))}`)}
 ${block("images", "Missing images", `<p>${m.inventory.missingFields.Image || 0} current physical SKUs have no populated image URL or media reference (${m.inventory.physicalSkus ? ((m.inventory.missingFields.Image || 0) / m.inventory.physicalSkus * 100).toFixed(1) : "0.0"}% of physical inventory). Video-only media does not satisfy image completeness; remote URL availability is not probed.</p>`)}
 ${block("certificates", "Certificate completeness", `<p>${m.inventory.certificateEligible === null ? "Certificate-required categories are not configured; assessment unavailable." : `${m.inventory.missingFields["Certificate number"] || 0} of ${m.inventory.certificateEligible} certificate-required SKUs lack a certificate number (${m.inventory.certificateEligible ? ((m.inventory.missingFields["Certificate number"] || 0) / m.inventory.certificateEligible * 100).toFixed(1) : "0.0"}%).`} Certificate-document availability is unavailable.</p>`)}
 ${block("requiredFields", "Missing required product fields", table(["Required field", "Affected SKUs"], Object.entries(m.inventory.missingFields).filter(([k]) => !["Image", "Certificate number"].includes(k))))}
 ${s.charts ? `<section><h2>History and operational charts</h2>${charts}</section>` : ""}
 ${block("actions", "Action items", m.alerts.map(x => `<div class="notice"><strong>${h(x.severity)} · ${h(x.message)}</strong><br>${h(x.action)}</div>`).join("") || "No configured thresholds exceeded.")}
 ${s.detailedSkus ? block("exceptions", "Other required-field exceptions", `<p class="muted">This concise register excludes image and certificate issues; those are shown as counts above.</p>${table(["SKU / product", "Stock / listings", "Missing requirements", "Corrective action"], exceptionRows)}`) : ""}
 ${block("coverage", "Data coverage and calculation notes", `<ul>${m.coverage.map(x => `<li>${h(x)}</li>`).join("")}<li>Intervals are inclusive at start and exclusive at end. Orders use source orderDate, sales use saleDate, publications use workPublication.publishedAt; inventory reflects generation time. Percentage changes are N/A when the prior value is zero.</li></ul>`, true)}
 </body></html>`;
}
export async function reportAssets(s: ReportSettings) {
 const approved = path.join(process.cwd(), "public/brand/khyatigems-logo.png");
 let bytes = await readFile(approved), mime = "image/png";
 if (s.logo === "COMPANY") {
  const c = await prisma.companySettings.findFirst(); const url = c?.otherDocsLogoUrl || c?.logoUrl;
  if (url?.startsWith("/") && !url.startsWith("//")) {
   const candidate = path.resolve(process.cwd(), "public", `.${url}`), root = path.resolve(process.cwd(), "public") + path.sep;
   if (!candidate.startsWith(root)) throw new Error("Invalid company logo path");
   bytes = await readFile(candidate); mime = candidate.endsWith(".svg") ? "image/svg+xml" : candidate.endsWith(".webp") ? "image/webp" : candidate.endsWith(".jpg") || candidate.endsWith(".jpeg") ? "image/jpeg" : "image/png";
  } else if (url) throw new Error("Company logo is remotely stored. Select the approved local logo or configure a local company asset before generating reports.");
 }
 if (bytes.length > 3000000) throw new Error("Company logo exceeds 3 MB");
 if (mime === "image/svg+xml") bytes = Buffer.from(sanitizeLogoSvg(bytes.toString()));
 return { logo: `data:${mime};base64,${bytes.toString("base64")}`, font: (await readFile(path.join(process.cwd(), "public/fonts/brand-font-0.ttf"))).toString("base64") };
}
export function verifyPdf(pdf: Buffer) { if (pdf.length < 1000 || pdf.subarray(0, 5).toString() !== "%PDF-" || !pdf.subarray(-100).toString().includes("%%EOF")) throw new Error("PDF validation failed"); }
export async function renderReport(m: Metrics, s: ReportSettings, mode: string) {
 const assets = await reportAssets(s);
 const browser = await puppeteer.launch({ headless: true, executablePath: process.env.REPORT_CHROME_EXECUTABLE_PATH || undefined, args: ["--no-sandbox", "--disable-setuid-sandbox", "--disable-dev-shm-usage"] });
 try {
  const page = await browser.newPage(); await page.setJavaScriptEnabled(false); await page.setRequestInterception(true);
  page.on("request", request => { if (request.url().startsWith("data:") || request.url() === "about:blank") void request.continue(); else void request.abort(); });
  await page.setContent(reportHtml(m, s, assets.logo, assets.font, mode), { waitUntil: "load", timeout: 45000 });
  await page.evaluate(() => document.fonts.ready);
  const bytes = Buffer.from(await page.pdf({ format: "A4", printBackground: true, margin: { top: "15mm", bottom: "20mm", left: "15mm", right: "15mm" }, displayHeaderFooter: true, headerTemplate: "<span></span>", footerTemplate: `<div style="font:8px Arial;width:100%;padding:0 15mm;color:#64748b"><span>${h(s.confidentiality)} · ${h(s.footer)}<br>${h(m.period.startDay)} – ${h(m.period.endDay)}</span><span style="float:right">Page <span class="pageNumber"></span> / <span class="totalPages"></span></span></div>` }));
  verifyPdf(bytes); return bytes;
 } finally { await browser.close(); }
}
